messages.content:
 1	method RemoveDuplicates(a: array<int>) returns (result: seq<int>)
 2	    requires a != null
 3	    ensures forall x :: x in result <==> exists i :: 0 <= i < a.Length && a[i] == x
 4	    ensures forall i, j :: 0 <= i < j < |result| ==> result[i] != result[j]
 5	{
 6	    var res: seq<int> := [];
 7	    for i := 0 to a.Length
 8	        invariant 0 <= i <= a.Length
 9	        invariant forall x :: x in res <==> exists k :: 0 <= k < i && a[k] == x
10	        invariant forall i, j :: 0 <= i < j < (|res|) - 1 ==> res[i] != res[j]
11	    {
12	        if a[i] !in res
13	        {
14	            res := res + [a[i]];
15	        }
16	    }
17	    result := res;
18	}

